'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const detail={BFE:'Full resolution · extent of realm',BFC:'Full resolution · coastline clipped',BGC:'Generalised · coastline clipped',BSC:'Super generalised · coastline clipped',BUC:'BUC · see source specification',Unspecified:'See source specification'};
let items=[],filtered=[],limit=25,shown={a:null,b:null},requestVersion=0,viewBox=[0,0,1000,540],fitBox=[0,0,1000,540];
const metadataCache=new Map();
function showTab(name){for(const b of document.querySelectorAll('.tab')){b.classList.toggle('active',b.dataset.tab===name);b.toggleAttribute('aria-current',b.dataset.tab===name);if(b.dataset.tab===name)b.setAttribute('aria-current','page');}for(const s of document.querySelectorAll('.view'))s.hidden=s.id!==name;}
for(const b of document.querySelectorAll('.tab'))b.addEventListener('click',()=>showTab(b.dataset.tab));
$('go-compare').onclick=()=>showTab('compare');
function options(el,values,first='All'){el.innerHTML=`<option value="">${esc(first)}</option>`+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');}
function defaults(){$('search').value='';$('family').value='Local authorities';$('year').value='';$('country').value='';$('kind').value='boundary';$('variant').value='';$('older').checked=false;limit=25;renderResults();}
function coverageIncludes(coverage,country){if(!country)return true;if(country===coverage)return true;if(['England','Wales','Scotland','Northern Ireland'].includes(country)){if(coverage==='UK')return true;if(coverage==='Great Britain'&&country!=='Northern Ireland')return true;if(coverage==='England & Wales'&&['England','Wales'].includes(country))return true;}return false;}
function renderResults(){const tokens=$('search').value.toLowerCase().trim().split(/\s+/).filter(Boolean);filtered=items.filter(x=>($('older').checked||x.year>=2010)&&(!$('family').value||x.family===$('family').value)&&(!$('year').value||x.year===Number($('year').value))&&coverageIncludes(x.coverage,$('country').value)&&(!$('kind').value||x.kind===$('kind').value)&&(!$('variant').value||x.variant===$('variant').value)&&tokens.every(t=>(x.title+' '+x.family+' '+x.coverage+' '+x.variant+' '+detail[x.variant]).toLowerCase().includes(t)));
 $('result-count').textContent=`${filtered.length} official ${filtered.length===1?'record':'records'}`;
 $('results').innerHTML=filtered.slice(0,limit).map(x=>`<article class="result"><div><div class="result-title">${esc(x.family)} · ${esc(x.vintage)}</div><span class="source-title">${esc(x.title)}</span><span class="tag">${esc(x.coverage)}</span><span class="tag">${esc(x.type)}</span></div><div><span class="data-label">Boundary detail</span><span class="data-value">${esc(detail[x.variant]||x.variant)}</span></div><div><span class="data-label">Source item updated</span><span class="data-value">${esc(x.modified)}</span><span class="source-title">Not an effective date</span></div><div class="result-actions"><a class="source-link" href="${esc(x.source)}" target="_blank" rel="noopener">Official source</a>${['Shapefile','CSV Collection','Microsoft Excel'].includes(x.type)?`<a href="https://www.arcgis.com/sharing/rest/content/items/${x.id}/data" target="_blank" rel="noopener">Download original file</a>`:''}${x.kind==='boundary'&&x.type==='Feature Service'?`<button class="text-button compare-item" data-id="${x.id}">Use on map</button>`:''}</div></article>`).join('');
 if(!filtered.length)$('results').innerHTML=`<div class="empty"><h3>No matching source in this index.</h3><p>${$('year').value==='2010'?'There is no explicitly labelled 2010 boundary file in this indexed collection. Enable pre-2010 reference vintages and inspect 2009, or check 2011; neither is automatically the boundary at your chosen date in 2010.':'Try removing the year or detail filter. Scottish and Northern Irish census products are linked under Coverage & sources, and have not yet been indexed.'}</p><button class="text-button" id="empty-coverage">View coverage & sources</button></div>`;
 if($('empty-coverage'))$('empty-coverage').onclick=()=>showTab('coverage');
 $('more').hidden=limit>=filtered.length;
 for(const b of document.querySelectorAll('.compare-item'))b.onclick=()=>{const item=items.find(x=>x.id===b.dataset.id);$('map-family').value=item.family;populateReleases(item.id);$('release-b').value=item.id;showTab('compare');$('map-status').textContent='Enter a place or GSS code, then compare.';};
}
for(const id of ['family','year','country','kind','variant','older'])$(id).onchange=()=>{limit=25;renderResults();};
$('search').oninput=()=>{const q=$('search').value.toLowerCase();const aliases=[[/\bmsoa\b/,'MSOA'],[/\blsoa\b/,'LSOA'],[/\bwards?\b/,'Wards'],[/\bconstituenc/,'Constituencies'],[/\bcode history\b/,'Code history'],[/\bcode register\b/,'Code register'],[/\blocal authorit/,'Local authorities'],[/\boutput areas?\b/,'Output areas'],[/\bregions?\b/,'English regions'],[/\bcombined authorit/,'Combined authorities'],[/\bmetropolitan count/,'Metropolitan counties']];const alias=aliases.find(([re])=>re.test(q));if(alias)$('family').value=alias[1];const year=q.match(/\b(20\d{2})\b/);if(year&&[...$('year').options].some(o=>o.value===year[1]))$('year').value=year[1];if(alias&&['Code history','Code register'].includes(alias[1]))$('kind').value='reference';else if(alias)$('kind').value='boundary';limit=25;renderResults();};
$('reset').onclick=defaults;$('more').onclick=()=>{limit+=25;renderResults();};
function download(data,filename,mime){const blob=new Blob([data],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(v){let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
$('export-index').onclick=()=>{const fields=['id','family','kind','vintage','year','coverage','variant','type','title','source','service','published','modified'];const rows=[fields.join(','),...filtered.map(x=>fields.map(f=>csvCell(x[f])).join(','))];download('\uFEFF'+rows.join('\r\n'),'uk-boundary-catalogue.csv','text/csv;charset=utf-8');};
function releaseItems(){return items.filter(x=>x.kind==='boundary'&&x.type==='Feature Service'&&x.service&&x.family===$('map-family').value).sort((a,b)=>b.year-a.year||a.title.localeCompare(b.title));}
function populateReleases(id){const available=releaseItems();for(const side of ['a','b'])$('release-'+side).innerHTML=available.map(x=>`<option value="${x.id}">${esc(x.vintage)} · ${esc(x.coverage)} · ${esc(x.variant)}</option>`).join('');const oldest=[...available].reverse().find(x=>x.year>=2010&&x.variant==='BGC')||available.at(-1);const newest=available.find(x=>x.variant==='BGC')||available[0];if(oldest)$('release-a').value=oldest.id;if(newest)$('release-b').value=newest.id;if(id)$('release-b').value=id;}
$('map-family').onchange=()=>{populateReleases();$('map-status').textContent='Choose the boundary vintages and enter a place or GSS code.';};
async function api(url,params){const u=new URL(url);if(params)for(const [k,v]of Object.entries(params))u.searchParams.set(k,v);const response=await fetch(u,{signal:AbortSignal.timeout(60000)});if(!response.ok)throw Error(`Official source returned HTTP ${response.status}.`);const data=await response.json();if(data.error)throw Error(data.error.message||'Official source query failed.');return data;}
async function layerInfo(item){if(metadataCache.has(item.id))return metadataCache.get(item.id);const root=await api(item.service,{f:'json'});let found;for(const entry of root.layers||[]){const m=await api(item.service+'/'+entry.id,{f:'json'});if(m.geometryType==='esriGeometryPolygon'){found={...m,layerUrl:item.service+'/'+entry.id};break;}}if(!found)throw Error('No polygon layer is available in this source.');metadataCache.set(item.id,found);return found;}
function stringFields(meta){return meta.fields.filter(f=>f.type==='esriFieldTypeString'&&(/(cd|nm|name|code)$/i.test(f.name)));}
async function fetchArea(item,term){if(!term.trim())throw Error('Enter a place name or GSS code for both snapshots.');const meta=await layerInfo(item),fields=stringFields(meta);if(!fields.length)throw Error('This source has no recognised place-name or code fields.');const safe=term.trim().toUpperCase().replace(/'/g,"''").replace(/[%_]/g,'');const isCode=/^[EWSNK]\d{8}$/i.test(term.trim());const where=fields.map(f=>`UPPER(${f.name}) ${isCode?'=':'LIKE'} '${isCode?safe:'%'+safe+'%'}'`).join(' OR ');const [geo,source]=await Promise.all([api(meta.layerUrl+'/query',{f:'geojson',where,outFields:'*',outSR:4326,returnGeometry:true,resultRecordCount:100}),api('https://www.arcgis.com/sharing/rest/content/items/'+item.id,{f:'json'})]);if(geo.exceededTransferLimit||geo.properties?.exceededTransferLimit)throw Error('Too many matching areas; use a more specific name or GSS code.');if(!Array.isArray(geo.features))throw Error('The source did not return a GeoJSON feature collection.');if(geo.features.length>=100)throw Error('At least 100 areas match; use a more specific name or GSS code.');return {item,term,geo,fields,layerUrl:meta.layerUrl,licence:source.licenseInfo||'See official source item.',copyright:meta.copyrightText||source.accessInformation||'',fetched:new Date().toISOString(),cached:false};}
function featureIdentity(feature){const props=feature.properties||{};const keys=Object.keys(props);const code=keys.find(k=>/cd$/i.test(k))||keys.find(k=>/^code$/i.test(k));const name=keys.find(k=>/nm$/i.test(k))||keys.find(k=>/^name$/i.test(k));return {code:code?String(props[code]):'',name:name?String(props[name]):'Unnamed area'};}
function projected([lon,lat]){return [lon*100,-Math.log(Math.tan(Math.PI/4+lat*Math.PI/360))*180/Math.PI*100];}
function polygons(geometry){if(!geometry)return [];if(geometry.type==='Polygon')return [geometry.coordinates];if(geometry.type==='MultiPolygon')return geometry.coordinates;return [];}
function drawMap(){const all=[],groups=[];for(const side of ['a','b']){const state=shown[side];if(!state)continue;const paths=state.geo.features.map(feature=>{let d='';for(const polygon of polygons(feature.geometry))for(const ring of polygon){const p=ring.map(projected);for(const xy of p)all.push(xy);d+=p.map((xy,i)=>(i?'L':'M')+xy.map(v=>v.toFixed(3)).join(' ')).join(' ')+'Z ';}const label=featureIdentity(feature);return `<path d="${d}" fill-rule="evenodd" vector-effect="non-scaling-stroke" stroke-width="2" stroke="${side==='a'?'#1668c6':'#d16b2d'}" fill="${side==='a'?'#2c87df':'#ef8b4c'}" fill-opacity="${side==='a'?'.18':'.25'}"><title>${esc(side.toUpperCase()+' · '+label.name+' · '+label.code)}</title></path>`;}).join('');groups.push(`<g id="layer-${side}" opacity="${side==='b'?Number($('opacity').value)/100:1}">${paths}</g>`);}
 $('geometry').innerHTML=groups.join('');if(all.length){let xmin=Infinity,xmax=-Infinity,ymin=Infinity,ymax=-Infinity;for(const [x,y]of all){xmin=Math.min(xmin,x);xmax=Math.max(xmax,x);ymin=Math.min(ymin,y);ymax=Math.max(ymax,y);}let w=xmax-xmin,h=ymax-ymin;w=Math.max(w,h*1000/540,.01)*1.15;h=w*540/1000;fitBox=[(xmin+xmax-w)/2,(ymin+ymax-h)/2,w,h];viewBox=[...fitBox];applyBox();}else{$('geometry').innerHTML='<text x="500" y="270" text-anchor="middle" fill="#546579" font-size="18">No matching polygons in the chosen snapshots</text>';viewBox=[0,0,1000,540];applyBox();}}
function applyBox(){$('map').setAttribute('viewBox',viewBox.join(' '));for(const [i,k]of ['x','y','width','height'].entries())$('map-bg').setAttribute(k,viewBox[i]);}
function zoom(factor){const [x,y,w,h]=viewBox;viewBox=[x+w*(1-factor)/2,y+h*(1-factor)/2,w*factor,h*factor];applyBox();}
$('zoom-in').onclick=()=>zoom(.75);$('zoom-out').onclick=()=>zoom(1.333);$('fit').onclick=()=>{viewBox=[...fitBox];applyBox();};$('opacity').oninput=()=>{const g=$('layer-b');if(g)g.setAttribute('opacity',Number($('opacity').value)/100);};
let drag;const svg=$('map');svg.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,box:[...viewBox]};svg.setPointerCapture(e.pointerId);});svg.addEventListener('pointermove',e=>{if(!drag)return;const rect=svg.getBoundingClientRect();const scale=Math.max(drag.box[2]/rect.width,drag.box[3]/rect.height);viewBox=[drag.box[0]-(e.clientX-drag.x)*scale,drag.box[1]-(e.clientY-drag.y)*scale,drag.box[2],drag.box[3]];applyBox();});svg.addEventListener('pointerup',()=>drag=null);svg.addEventListener('pointercancel',()=>drag=null);
function renderDetails(){for(const side of ['a','b']){const state=shown[side];$('download-'+side).disabled=!state||!state.geo.features.length;if(!state){$('details-'+side).textContent='No snapshot loaded.';continue;}const {item,geo}=state;$('details-'+side).innerHTML=`<p>${esc(item.title)}</p><a href="${esc(item.source)}" target="_blank" rel="noopener">Official source and licence</a><ul class="feature-list">${geo.features.map(f=>{const x=featureIdentity(f);return `<li>${esc(x.name)} <span class="tag">${esc(x.code)}</span></li>`;}).join('')}</ul>${!geo.features.length?'<p>No place with this name or code matched this vintage.</p>':''}${state.cached?'<p class="small">Saved example, retrieved 6 October 2026.</p>':''}`;}
 const a=shown.a,b=shown.b;if(!a||!b)return;const codesA=a.geo.features.map(f=>featureIdentity(f).code).filter(Boolean),codesB=b.geo.features.map(f=>featureIdentity(f).code).filter(Boolean),shared=codesA.filter(c=>codesB.includes(c));$('map-summary').innerHTML=`<span><strong>${a.geo.features.length}</strong> matched areas in A</span><span><strong>${b.geo.features.length}</strong> matched areas in B</span><span><strong>${shared.length}</strong> shared GSS ${shared.length===1?'code':'codes'} in these snapshots</span>`;if(a.item.variant!==b.item.variant)$('map-summary').innerHTML+='<span><strong>Detail levels differ.</strong> Select matching variants before interpreting edges.</span>';if(a.item.coverage!==b.item.coverage)$('map-summary').innerHTML+='<span>Source coverage differs; matches may be absent outside a source’s coverage.</span>';}
async function compare(){const run=++requestVersion;const button=$('load-map');button.disabled=true;$('map-status').textContent='Querying official boundary services…';shown={a:null,b:null};$('geometry').innerHTML='';$('map-summary').textContent='';for(const side of ['a','b']){$('download-'+side).disabled=true;$('details-'+side).textContent='Loading…';}try{const results=await Promise.allSettled(['a','b'].map(side=>fetchArea(items.find(x=>x.id===$('release-'+side).value),$('place-'+side).value)));if(run!==requestVersion)return;const errors=[];results.forEach((r,i)=>{if(r.status==='fulfilled')shown[['a','b'][i]]=r.value;else errors.push((i?'B':'A')+': '+r.reason.message);});drawMap();renderDetails();$('map-status').textContent=errors.length?errors.join(' '):'Official polygons loaded. Hover an area for its name and code.';}catch(e){$('map-status').textContent=e.message;}finally{if(run===requestVersion)button.disabled=false;}}
$('load-map').onclick=compare;for(const side of ['a','b'])$('place-'+side).addEventListener('keydown',e=>{if(e.key==='Enter')compare();});
for(const side of ['a','b'])$('download-'+side).onclick=()=>{const state=shown[side];if(!state)return;const data={...state.geo,boundaryAtlas:{sourceItemId:state.item.id,sourceTitle:state.item.title,sourceUrl:state.item.source,serviceLayer:state.layerUrl,boundaryVintage:state.item.vintage,detail:state.item.variant,coverage:state.item.coverage,query:state.term,retrievedAt:state.fetched,crs:'EPSG:4326; longitude, latitude',licence:state.licence,copyright:state.copyright,scope:'Matched areas only; boundary vintage is not a certified legal validity interval.'}};download(JSON.stringify(data,null,2),`${state.term.replace(/[^a-z0-9_-]/gi,'_')}_${state.item.year}_${side.toUpperCase()}.geojson`,'application/geo+json');};
async function init(){try{const response=await fetch('catalogue.json');if(!response.ok)throw Error('Catalogue could not be loaded.');const data=await response.json();items=data.items;options($('family'),[...new Set(items.map(x=>x.family))].sort(),'All reporting levels');options($('year'),Array.from({length:17},(_,i)=>String(2026-i)),'All vintages');defaults();renderParity();options($('map-family'),[...new Set(items.filter(x=>x.kind==='boundary'&&x.type==='Feature Service').map(x=>x.family))].sort(),'Choose level');$('map-family').value='Local authorities';populateReleases();try{const sample=await fetch('kirklees-example.json');if(!sample.ok)throw Error();const data=await sample.json();shown={a:data.a,b:data.b};for(const side of ['a','b']){$('release-'+side).value=shown[side].item.id;shown[side].cached=true;}drawMap();renderDetails();$('map-status').textContent='Kirklees example · official snapshots retrieved 6 October 2026. Compare again to refresh.';}catch{await compare();}}catch(e){$('result-count').textContent='Catalogue unavailable';$('results').textContent=e.message;}}
function renderParity(){const years=Array.from({length:17},(_,i)=>2010+i);const families=['Output areas','LSOA','MSOA','Local authorities','Counties / upper tier','Metropolitan counties','Combined authorities','English regions','NUTS 1 regions (historic)','ITL 1 regions','NUTS 2 regions (historic)','ITL 2 regions','NUTS 3 regions (historic)','ITL 3 regions','Countries','Wards','Constituencies'];const labels={'Output areas':'OA · England & Wales','LSOA':'LSOA · England & Wales','MSOA':'MSOA · England & Wales','Local authorities':'LAD / UA / council areas','Metropolitan counties':'Metropolitan counties · England','Combined authorities':'Combined authorities · England'};$('parity').innerHTML='<table><caption>Source snapshot availability by reporting level and reference year</caption><thead><tr><th scope="col">Reporting level</th>'+years.map(y=>`<th scope="col">${y}</th>`).join('')+'</tr></thead><tbody>'+families.map(f=>'<tr><th scope="row">'+esc(labels[f]||f)+'</th>'+years.map(y=>items.some(x=>x.family===f&&x.kind==='boundary'&&x.year===y)?`<td><button class="coverage-cell" data-family="${esc(f)}" data-year="${y}" title="Show ${esc(f)}, ${y}" aria-label="Show ${esc(f)} source snapshots for ${y}">✓</button></td>`:'<td><span title="No indexed snapshot">—</span></td>').join('')+'</tr>').join('')+['OA · Scotland','Data Zones · Scotland','Intermediate Zones · Scotland','Small Areas / Data Zones · NI','SOA / Super Data Zones · NI'].map(f=>`<tr><th scope="row">${f}</th><td colspan="17" class="pending">Official sources linked below · historical ingestion pending</td></tr>`).join('')+'</tbody></table>';for(const b of document.querySelectorAll('.coverage-cell'))b.onclick=()=>{$('family').value=b.dataset.family;$('year').value=b.dataset.year;$('search').value='';$('country').value='';$('variant').value='';$('kind').value='boundary';limit=25;renderResults();showTab('catalogue');};}
init();


